// Arbeitsliste als HTML-Seite: Überblick, offene Aufgaben nach Team, Review-Queue. Werte werden escaped, weil Mailtexte von außen kommen.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const tag = (t, klasse = '') => `<span class="tag ${klasse}">${esc(t)}</span>`;
const reviews = $('Offene Reviews laden').all().map((i) => i.json).filter((r) => r.id);
const tickets = $('Tickets laden').all().map((i) => i.json).filter((r) => r.id);

const KATEGORIE = {
  angebot: 'Angebot', auftragsbestaetigung: 'Auftragsbestätigung', reklamation: 'Reklamation', lieferverzug: 'Lieferverzug',
  rechnung: 'Rechnung', lieferavis: 'Lieferavis', preisaenderung: 'Preisänderung', stammdatenaenderung: 'Stammdatenänderung',
  compliance: 'Compliance', werbung: 'Werbung', sonstiges: 'Sonstiges',
};

// Abweichungen und Prüfgründe der AB-Prüfung in Sätze übersetzen, die ein Einkäufer sofort versteht
const beschreibe = (ab) => {
  const zahl = (n) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 });
  const datum = (d) => (d ? (typeof d === 'string' ? d : new Date(d).toISOString()).slice(0, 10).split('-').reverse().join('.') : '–');
  const texte = (ab.abweichungen ?? []).map((a) => ({
    preis: `Preis ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)} ${a.waehrung ?? ''}`,
    waehrung: `Währung ${a.bestellt} → ${a.bestaetigt}: Preis in anderer Währung bestätigt`,
    menge: `Menge ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)}${a.grund ? ` (${a.grund})` : ''}`,
    stammdaten_pruefen: `Stammdaten prüfen${a.hinweis ? `: ${a.hinweis}` : ''}`,
    termin_unsicher: `Termin unsicher, gewünscht ${datum(a.gewuenscht)}`,
    termin_fehlt: `Kein Termin bestätigt, gewünscht ${datum(a.gewuenscht)}`,
    termin_spaeter: `Termin ${datum(a.gewuenscht)} → ${datum(a.bestaetigt)}`,
  }[a.art] ?? a.art));
  for (const g of ab.pruefgruende ?? []) {
    texte.push({
      neuer_lieferant: 'Neuer Lieferant: Kontakt aufnehmen und Termin absichern',
      liefertreue_unter_schwelle: `Liefertreue ${ab.liefertreue} % unter ${ab.schwelle} % (${ab.abc_xyz}-Artikel)`,
      blindbestaetigung_verdacht: `AB nach ${ab.bearbeitungszeit_minuten} Minuten: Blindbestätigung?`,
      absender_domain_abweichend: 'Absender-Domain passt nicht zum Lieferanten',
    }[g] ?? g);
  }
  return texte;
};

// Hinweise des Systems (Belegprüfung, Korrekturen) in lesbare Form bringen
const FELD = { einzelpreis: 'Einzelpreis', menge: 'Menge', betrag: 'Betrag', liefertermin: 'Liefertermin', bestellnummer: 'Bestellnummer', rechnungsnummer: 'Rechnungsnummer', angebotsnummer: 'Angebotsnummer' };
const warnung = (w) => {
  const [art, wert] = String(w).split(':');
  if (art === 'beleg_fehlt') return `${FELD[wert] ?? wert} nicht im Mailtext belegt, bitte prüfen`;
  if (art === 'kategorie_korrigiert') return 'Kategorie automatisch korrigiert (Bestellnummer und AB-Wortlaut)';
  return String(w);
};

const GRUND = {
  konfidenz_niedrig: 'Modell war unsicher', bankdatenaenderung: 'Bankdaten geändert: Betrugsverdacht', stammdatenaenderung_pruefen: 'Stammdatenänderung: immer prüfen',
  prompt_injection_verdacht: 'Verdacht auf Manipulation des Modells', bestellung_unbekannt: 'Bestellnummer nicht im System', kategorie_unplausibel: 'Kategorie unplausibel',
  llm_fehler: 'Modell nicht erreichbar', json_ungueltig: 'Antwort des Modells ungültig', schema_verletzt: 'Antwort des Modells ungültig',
};
const grund = (g) => (String(g).startsWith('pflichtfeld_fehlt:') ? `Pflichtangabe fehlt: ${String(g).split(':')[1].replace('|', ' oder ')}` : GRUND[g] ?? String(g));

const adresse = (absender) => String(absender ?? '').match(/<([^>]+)>/)?.[1] ?? String(absender ?? '').trim();
const anbieter = (t) => t.lieferant || String(t.absender ?? '').replace(/<[^>]*>/g, '').trim() || 'Unbekannter Absender';
const mailto = (an, betreff, text) => `mailto:${esc(encodeURIComponent(an ?? '').replace(/%40/g, '@'))}?subject=${esc(encodeURIComponent(betreff ?? ''))}&amp;body=${esc(encodeURIComponent(text ?? ''))}`;

// Anfrage (RFQ) im Format, das der Procurement-RAG-Agent auslesen kann: eine Angabe je Zeile, mit Einheit
const rfq = (t) => {
  const gegenstand = t.artikel || (t.kategorie === 'angebot' ? t.betreff : '[Artikel eintragen]');
  const einleitung = t.kategorie === 'preisaenderung'
    ? `vielen Dank für Ihre Information zur Preisänderung. Bevor wir entscheiden, möchten wir ein aktuelles, vollständiges Angebot einholen für: ${gegenstand}.`
    : `vielen Dank für Ihr Angebot. Damit wir es mit anderen vergleichen können, bitten wir um ein vollständiges Angebot zu: ${gegenstand}.`;
  return {
    betreff: `Anfrage (RFQ): ${gegenstand}`,
    text: [
      'Guten Tag,',
      '',
      einleitung,
      '',
      'Bitte beantworten Sie jeden Punkt einzeln und mit Einheit, damit wir Angebote vergleichen können:',
      '1. Stückpreis in EUR, netto, je 1 Stück',
      '2. Mindestbestellmenge in Stück',
      '3. Lieferzeit in Tagen nach Auftragseingang',
      '4. Zahlungsziel in Tagen',
      '5. Skonto in Prozent (0, wenn keines)',
      '6. Preisgleitklausel: ja oder nein (Preis an einen Index gekoppelt?)',
      '7. Zertifizierung ISO 9001: gültig ja oder nein, mit Gültigkeitsdatum',
      '8. Zertifizierung ISO 14001: gültig ja oder nein, mit Gültigkeitsdatum',
      '9. CO2-Fußabdruck je Stück in kg CO2e',
      '10. Reklamationsquote in Prozent (letzte 12 Monate)',
      '11. Liefertreue in Prozent (letzte 12 Monate)',
      '',
      'Bitte senden Sie das Angebot als PDF mit Angebotsnummer und Gültigkeitsdatum sowie die ausgefüllte Lieferantenselbstauskunft.',
      'Angebotsfrist: [Datum eintragen]',
      '',
      'Mit freundlichen Grüßen',
      '[Name]',
      'Hagemann Antriebstechnik GmbH, Einkauf',
    ].join('\n'),
  };
};

const FARBE = { hoch: 'hoch', mittel: 'mittel', niedrig: 'niedrig' };

const karte = (t) => {
  const ab = t.ab_pruefung ?? {};
  const chips = [
    ...(t.kategorie === 'auftragsbestaetigung' ? beschreibe(ab).map((x) => tag(x, 'warn')) : []),
    ...(t.warnungen ?? []).filter((w) => !String(w).startsWith('kategorie_korrigiert')).map((w) => tag(warnung(w), 'info')),
  ].join(' ');
  const mailtext = t.entwurf_text
    ? `<details><summary>Antwortentwurf (${esc(t.foermlichkeit)}, ${esc(t.nachdruck)})</summary>
        ${(t.entwurf_warnungen ?? []).length ? `<p class="warnung">Bitte prüfen: ${t.entwurf_warnungen.map(esc).join(', ')}</p>` : ''}
        <pre><b>${esc(t.entwurf_betreff)}</b>\n\n${esc(t.entwurf_text)}</pre>
        <a class="knopf" href="${mailto(t.entwurf_empfaenger, t.entwurf_betreff, t.entwurf_text)}">In Mailprogramm öffnen</a></details>`
    : '';
  const anfrage = ['angebot', 'preisaenderung'].includes(t.kategorie) ? rfq(t) : null;
  const anfrageBlock = anfrage
    ? `<details><summary>Angebot anfordern (RFQ-Entwurf)</summary>
        <pre><b>${esc(anfrage.betreff)}</b>\n\n${esc(anfrage.text)}</pre>
        <a class="knopf" href="${mailto(adresse(t.absender), anfrage.betreff, anfrage.text)}">In Mailprogramm öffnen</a></details>`
    : '';
  const meta = [t.bestellnummer ? `Bestellung ${t.bestellnummer}` : '', t.artikel, t.angebotsnummer ? `Angebot ${t.angebotsnummer}` : '',
    t.rechnungsnummer ? `Rechnung ${t.rechnungsnummer}` : '', t.betrag ? `${Number(t.betrag).toLocaleString('de-DE', { minimumFractionDigits: 2 })} ${t.waehrung ?? ''}` : '',
    t.zustaendig ? `zuständig: ${t.zustaendig}` : '', t.erstellt].filter(Boolean).map(esc).join(' · ');
  const knopfZeile = t.status === 'offen'
    ? `<form method="post" action="/webhook/aufgabe"><input type="hidden" name="id" value="${esc(t.id)}"><button class="knopf haupt" type="submit">Erledigt</button></form>
       ${t.kategorie === 'auftragsbestaetigung' && !t.entwurf_text && beschreibe(ab).length ? '<a class="knopf" href="/form/entwurf">Antwortentwurf erstellen</a>' : ''}`
    : '';
  return `<article class="dringlich-${FARBE[t.dringlichkeit] ?? 'niedrig'}">
    <div class="kopf"><span class="kat">${esc(KATEGORIE[t.kategorie] ?? t.kategorie)}</span><h3>${esc(anbieter(t))}: ${esc(t.betreff)}</h3></div>
    ${t.zusammenfassung ? `<p class="zusammenfassung">${esc(t.zusammenfassung)}</p>` : ''}
    <p class="meta">${meta}</p>
    ${chips ? `<p>${chips}</p>` : ''}
    ${mailtext}${anfrageBlock}
    <div class="aktionen">${knopfZeile}</div>
  </article>`;
};

const offen = tickets.filter((t) => t.status === 'offen');
const automatisch = tickets.filter((t) => ['bestaetigt', 'abgelegt'].includes(t.status));
const REIHENFOLGE = ['Einkauf', 'Strategischer Einkauf', 'Disposition', 'Qualitätsmanagement', 'Kreditorenbuchhaltung', 'Einkauf Sammelpostfach'];
const teams = [...new Set(offen.map((t) => t.team))].sort((a, b) => (REIHENFOLGE.indexOf(a) + 100) % 100 - (REIHENFOLGE.indexOf(b) + 100) % 100);
const teamBloecke = teams.map((team) => {
  const liste = offen.filter((t) => t.team === team);
  return `<section><h2>${esc(team)} <span class="zahl">${liste.length}</span></h2>${liste.map(karte).join('')}</section>`;
}).join('');

const reviewKarten = reviews.map((r) => `
  <article>
    <div class="kopf"><span class="kat">Review</span><h3>${esc(r.betreff)}</h3></div>
    <p class="meta">${esc(r.absender)} · ${esc(r.erstellt)}</p>
    <p>${r.gruende.map((g) => tag(grund(g), 'warn')).join(' ')}</p>
    <p class="zusammenfassung">Vorschlag des Modells: ${esc(KATEGORIE[r.vorschlag] ?? r.vorschlag ?? '–')} (Konfidenz ${esc(r.konfidenz ?? '–')}). ${esc(r.begruendung ?? '')}</p>
    <details><summary>Mailtext</summary><pre>${esc(r.text)}</pre></details>
    <div class="aktionen"><a class="knopf haupt" href="/form/review">Review abschließen (ID ${esc(r.id)})</a></div>
  </article>`).join('');

const automatischZeilen = automatisch.slice(0, 30).map((t) =>
  `<li><span class="kat klein">${esc(KATEGORIE[t.kategorie] ?? t.kategorie)}</span> ${esc(anbieter(t))}: ${esc(t.betreff)} <span class="meta">· ${esc(t.status === 'abgelegt' ? 'abgelegt' : 'automatisch bestätigt')} · ${esc(t.erstellt)}</span></li>`).join('');

const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Arbeitsliste Einkauf</title>
<style>
  :root { --text: #1f2328; --grau: #656d76; --linie: #d8dee4; --flaeche: #f6f8fa; --blau: #1f6feb; --orange: #9a4b00; --orange-bg: #fff1e5; }
  * { box-sizing: border-box; }
  body { font-family: system-ui, -apple-system, 'Segoe UI', sans-serif; max-width: 960px; margin: 0 auto; padding: 1.5rem 1rem 3rem; color: var(--text); background: #fff; line-height: 1.45; }
  h1 { font-size: 1.5rem; margin: 0 0 .25rem; } h2 { font-size: 1.1rem; margin: 2rem 0 .75rem; display: flex; align-items: center; gap: .5rem; }
  h3 { font-size: 1rem; margin: 0; font-weight: 600; }
  .untertitel { color: var(--grau); margin: 0 0 1.25rem; }
  .kennzahlen { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: .75rem; margin-bottom: 1rem; }
  .kennzahl { border: 1px solid var(--linie); border-radius: 8px; padding: .75rem 1rem; background: var(--flaeche); }
  .kennzahl b { display: block; font-size: 1.6rem; line-height: 1.1; } .kennzahl span { color: var(--grau); font-size: .85rem; }
  .zahl { background: var(--flaeche); border: 1px solid var(--linie); border-radius: 999px; font-size: .8rem; padding: 0 .55rem; color: var(--grau); font-weight: 500; }
  article { border: 1px solid var(--linie); border-left: 4px solid var(--linie); border-radius: 8px; padding: .85rem 1.1rem; margin-bottom: .75rem; }
  article.dringlich-hoch { border-left-color: #cf222e; } article.dringlich-mittel { border-left-color: #d4a72c; }
  .kopf { display: flex; gap: .6rem; align-items: baseline; flex-wrap: wrap; }
  .kat { background: #ddf4ff; color: #0550ae; border-radius: 4px; padding: .05rem .45rem; font-size: .78rem; font-weight: 600; white-space: nowrap; }
  .kat.klein { font-size: .72rem; }
  .zusammenfassung { margin: .35rem 0; } .meta { color: var(--grau); margin: .2rem 0 .5rem; font-size: .88rem; }
  .tag { display: inline-block; border-radius: 4px; padding: .1rem .45rem; margin: .1rem .15rem .1rem 0; font-size: .82rem; }
  .tag.warn { background: var(--orange-bg); color: var(--orange); } .tag.info { background: var(--flaeche); color: var(--grau); border: 1px solid var(--linie); }
  .warnung { color: var(--orange); margin: .4rem 0; }
  pre { white-space: pre-wrap; background: var(--flaeche); padding: .75rem; border-radius: 6px; font-family: inherit; margin: .5rem 0; }
  details { margin: .4rem 0; } summary { cursor: pointer; color: var(--blau); }
  .aktionen { display: flex; gap: .5rem; flex-wrap: wrap; margin-top: .5rem; } .aktionen form { margin: 0; }
  .knopf { display: inline-block; border: 1px solid var(--linie); background: #fff; color: var(--text); padding: .4rem .85rem; border-radius: 6px; text-decoration: none; font: inherit; font-size: .9rem; cursor: pointer; }
  .knopf:hover { background: var(--flaeche); } .knopf.haupt { background: var(--blau); border-color: var(--blau); color: #fff; } .knopf.haupt:hover { background: #1a5fd0; }
  ul.liste { list-style: none; padding: 0; margin: .5rem 0; } ul.liste li { padding: .3rem 0; border-bottom: 1px solid var(--linie); font-size: .92rem; }
  .leer { color: var(--grau); }
</style></head><body>
<h1>Arbeitsliste Einkauf</h1>
<p class="untertitel">Hier landen die Lieferanten-Mails, sortiert nach zuständigem Team.</p>
<div class="kennzahlen">
  <div class="kennzahl"><b>${offen.length}</b><span>offene Aufgaben</span></div>
  <div class="kennzahl"><b>${reviews.length}</b><span>Mails zur Prüfung</span></div>
  <div class="kennzahl"><b>${automatisch.length}</b><span>automatisch erledigt (7 Tage)</span></div>
</div>
${reviews.length ? `<section><h2>Zur Prüfung <span class="zahl">${reviews.length}</span></h2><p class="meta">Das System war unsicher oder hat einen Verdachtsfall erkannt. Ein Mensch entscheidet, wohin die Mail gehört.</p>${reviewKarten}</section>` : ''}
${teamBloecke || '<p class="leer">Keine offenen Aufgaben.</p>'}
${automatisch.length ? `<section><h2>Automatisch erledigt <span class="zahl">${automatisch.length}</span></h2><details><summary>Anzeigen</summary><ul class="liste">${automatischZeilen}</ul></details></section>` : ''}
</body></html>`;

return { json: { html } };

// Nur Aufrufe von der eigenen Seite zulassen (Schutz vor fremden Seiten, die den Browser mit seiner Anmeldung missbrauchen)
const kopf = $json.headers ?? {};
const herkunft = String(kopf.origin ?? kopf.referer ?? '');
const herkunftHost = herkunft.replace(/^https?:\/\//, '').split('/')[0];
const gleicheHerkunft = herkunftHost !== '' && herkunftHost === kopf.host;
const id = Number($json.body?.id);
return { json: { gueltig: gleicheHerkunft && Number.isInteger(id) && id > 0, id } };
